DO $$ DECLARE job record; url text; BEGIN FOR job IN SELECT jobid,command FROM cron.job WHERE command NOT LIKE '%x-cron-key%' AND command LIKE '%/api/public/hooks/%' LOOP url := substring(job.command from 'https://[^''[:space:]]+'); IF url IS NULL THEN RAISE EXCEPTION 'Missing job URL'; END IF; PERFORM cron.alter_job(job.jobid, command := format('SELECT net.http_post(url := %L, headers := jsonb_build_object(''Content-Type'',''application/json'',''x-cron-key'',(SELECT secret FROM private.cron_key WHERE id=1)), body := ''{}''::jsonb);',url)); END LOOP; END $$;
DO $$ DECLARE pol record; BEGIN FOR pol IN SELECT tablename,policyname,cmd,roles FROM pg_policies WHERE schemaname='public' AND qual='true' AND cmd='SELECT' AND tablename IN ('event_bot_knowledge','event_merch_options','event_photos_cache','event_price_book','event_info_blocks','event_venues','event_village_maps','event_village_tent_rules','event_village_tents','feed_posts','loyalty_event_values') LOOP EXECUTE format('ALTER POLICY %I ON public.%I USING (private.event_visible(event_id))',pol.policyname,pol.tablename); END LOOP; END $$;